import{z as B,x as A,o as r,c as d,q as l,j as s,D as n,d as E,s as i,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"按需调页","description":"","frontmatter":{"title":"按需调页","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/demand-paging.md","filePath":"cs/demand-paging.md","lastUpdated":1791063341000}'),p={name:"cs/demand-paging.md"};function m(C,a,h,c,D,f){const t=A("Mermaid");return r(),d("div",null,[a[2]||(a[2]=l('<h1 id="按需调页" tabindex="-1">按需调页 <a class="header-anchor" href="#按需调页" aria-label="Permalink to &quot;按需调页&quot;">​</a></h1><div class="epigraph"><p>不必在运行前把程序全部装入内存；第一次访问某页时再为它分配物理页。</p><footer>—— 据 Denning, The Working Set Model for Program Behavior, CACM 1968；Silberschatz et al. 整理</footer></div><p><a href="/cs/brk-heap">上一课</a>画出合法虚区间，许多页此刻仍无物理页。<a href="/cs/paging-vm">分页</a>的缺页异常已经能进内核。<a href="/cs/load-dynlink">加载</a>若一次装入全部文本，启动慢且浪费。<a href="/cs/tlb-translate">TLB</a> 仍只缓存已填的翻译。缺口是<strong>按需</strong>：访问到再补页。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>进程虚空间可以远大于物理内存。若启动时为每页分配帧，机器跑不了几个进程。若永远不分配，第一次取指令就无翻译。缺口不是新的页表格式，而是策略：页表项先标无效；缺页时内核分配帧、必要时从可执行文件或交换区读入、填表、再执行那条指令。</p><p><span class="marginnote">数字实例：页大小 4 KB 时，一个声明了 2 GB 虚空间的进程共有约 52 万页。若启动即全额装帧，在一台 8 GB 内存的机器上要一次吃掉四分之一物理内存；而按需调页下，真正驻留的可能只有热循环所在的几十页。几十 KB 与 2 GB 的差距，就是「按需」两个字换来的。</span></p><p>本课不选哪一页被换出，那是下一课置换。这里假定「还有空闲帧」。</p><p><span class="marginnote">工作集：近期触碰的页集合。Denning 用它解释为何按需加上局部性后，驻留集可以远小于虚空间。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>用户访问 → MMU 走页表 → 无效 → 缺页陷入（组成课入口）→ 内核看是非法地址则杀进程或给信号，合法则分配帧、填内容、置有效与权限 → 返回用户，硬件重试指令。文本页内容来自文件；匿名页可先填零。预调（把相邻页一并装入）是可选优化，不改「第一次触及才必须正确」这条。</p>',10)),(r(),s(o,null,{default:n(()=>[i(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20ACC%5B%22%E8%AE%BF%E9%97%AE%E8%99%9A%E9%A1%B5%22%5D%20--%3E%20FAULT%5B%22%E7%BC%BA%E9%A1%B5%E9%99%B7%E5%85%A5%22%5D%0A%20%20FAULT%20--%3E%20ALLOC%5B%22%E5%88%86%E9%85%8D%E7%89%A9%E7%90%86%E5%B8%A7%22%5D%0A%20%20ALLOC%20--%3E%20FILL%5B%22%E5%A1%AB%E6%96%87%E4%BB%B6%E6%88%96%E9%9B%B6%E9%A1%B5%22%5D%0A%20%20FILL%20--%3E%20RETRY%5B%22%E9%87%8D%E8%AF%95%E6%8C%87%E4%BB%A4%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("按需把"),e("a",{href:"/cs/locality-principle"},"局部性"),E("从 Cache 课接到 OS：只有工作集占物理内存。系统调用 "),e("code",null,"exec"),E(" 可以只建页表骨架，几乎不读磁盘，直到入口指令缺页。与运行时 GC 不同：GC 回收的是语言对象；调页回收的是帧——还没到回收，下一课才缺帧。")],-1)),a[5]||(a[5]=e("p",null,"权限仍来自分页课：只读文本写了是保护错，不是「再调一页可写」。",-1)),a[6]||(a[6]=e("p",null,"内核接到缺页陷入后，第一件事不是调页，而是分清这次陷入属于哪一类：",-1)),(r(),s(o,null,{default:n(()=>[i(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E7%BC%BA%E9%A1%B5%E9%99%B7%E5%85%A5%22%5D%20--%3E%20CHK%7B%22%E5%9C%B0%E5%9D%80%E5%90%88%E6%B3%95%E4%B8%94%E6%9D%83%E9%99%90%E5%85%81%E8%AE%B8%EF%BC%9F%22%7D%0A%20%20CHK%20--%3E%7C%22%E9%9D%9E%E6%B3%95%E5%9C%B0%E5%9D%80%20%2F%20%E8%B6%8A%E6%9D%83%22%7C%20KILL%5B%22%E6%AE%B5%E9%94%99%E8%AF%AF%EF%BC%9A%E6%9D%80%E8%BF%9B%E7%A8%8B%E6%88%96%E5%8F%91%E4%BF%A1%E5%8F%B7%22%5D%0A%20%20CHK%20--%3E%7C%22%E5%90%88%E6%B3%95%E4%BD%86%E9%A1%B5%E8%A1%A8%E9%A1%B9%E6%97%A0%E6%95%88%22%7C%20ALLOC%5B%22%E6%8C%89%E9%9C%80%E8%B0%83%E9%A1%B5%EF%BC%9A%E5%88%86%E9%85%8D%E5%B8%A7%E3%80%81%E5%A1%AB%E5%86%85%E5%AE%B9%E3%80%81%E9%87%8D%E8%AF%95%22%5D%0A%20%20CHK%20--%3E%7C%22%E5%86%99%E5%8F%AA%E8%AF%BB%E9%A1%B5%22%7C%20PROT%5B%22%E4%BF%9D%E6%8A%A4%E9%94%99%EF%BC%9A%E6%8C%89%E4%BF%A1%E5%8F%B7%E5%A4%84%E7%90%86%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p><span class="marginnote">直觉类比：按需调页像图书馆按需取书——办了借书证（虚空间）不等于把整个书架搬回家；读到缺的那本，管理员（内核）才去书库取来放到桌上（分配帧），你再把那一句从头读一遍（重试指令）。证上的书目再多，桌上同时摊开的始终只有几本。</span></p><p><span class="marginnote">常见误区：初学者容易把所有「缺页」都当成事故。按需调页下的第一次触及缺页是正常机制，代价只是一次读文件；真正危险的是下一课的抖动——帧不够时频繁换入换出，CPU 全耗在搬运上。另外注意：写只读页报的是保护错，缺页机制救不了它。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入倒排页表实现，不把巨型页当默认。也不把交换分区的槽位分配写完。网络文件系统上的按需读文件，语义仍是「缺页时填」，延迟更大而已。</p><p>指令重试要求精确异常：缺页的那条 load/store 不能已经写坏寄存器。组成课已经要求精确，本课直接用。</p><p>后课默认：合法访问可以在缺页时才占帧。帧不够时淘汰谁，下一课缺页与置换。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>页先无效，触及再分配并填内容。</li><li>工作集解释为何虚大于物仍可跑。</li><li>无空闲帧时的淘汰是下一课。</li><li>出处：Denning, <em>CACM</em> 1968；Silberschatz et al., <em>OSC</em>；Tanenbaum <em>MOS</em>。</li></ul>',8))])}const F=B(p,[["render",m]]);export{u as __pageData,F as default};
